export default function Grid({ children, cols = 1, gap = 4, className = '', ...props }) {
  const colsMap = {
    1: 'grid-cols-1',
    2: 'grid-cols-1 md:grid-cols-2',
    3: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3',
    4: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-4',
    6: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6'
  };

  return (
    <div className={`grid ${colsMap[cols] || colsMap[1]} gap-${gap} ${className}`} {...props}>
      {children}
    </div>
  );
}
